# Verified source allocation and frozen contractual budget projection checks.
.va_differences<-function(a,b,tolerance,path=''){number<-function(v)is.numeric(v)&&length(v)==1&&is.null(dim(v));if(number(a)&&number(b))return(if(abs(a-b)<=max(tolerance,tolerance*max(abs(a),abs(b))))character()else path);if(.cr_object(a)&&.cr_object(b)){out<-if(setequal(names(a),names(b)))character()else paste0(path,'/<keys>');for(key in sort(intersect(names(a),names(b))))out<-c(out,.va_differences(a[[key]],b[[key]],tolerance,paste0(path,'/',key)));return(out)};if(is.list(a)&&is.null(names(a))&&is.list(b)&&is.null(names(b))){out<-if(length(a)==length(b))character()else paste0(path,'/<length>');for(i in seq_len(min(length(a),length(b))))out<-c(out,.va_differences(a[[i]],b[[i]],tolerance,paste0(path,'/',i-1)));return(out)};if(identical(.cr_hash(a),.cr_hash(b)))character()else path}
affordability_stress_backtest<-function(cases,economic_evidence,allocations,design,payment_outcomes=NULL,tolerance=1e-10,uncertainty='none',cluster_resamples=NULL,confidence_level=.95,context=NULL){
 d<-.vb_design(design,context);currency<-.vb_string(d$currency,'design currency');tol<-.vb_number(tolerance,'tolerance',0);rows<-.vr_rows(cases,'cases');rows<-lapply(rows,function(row){if(inherits(row$assessment,'CalcResult'))row$assessment<-row$assessment$value;row});rows<-.vb_records(rows,d);ee<-.vs_index(economic_evidence,'evidence_id','economic_evidence');proofs<-ee$rows;ei<-ee$index;shares<-.vs_index(allocations,'allocation_id','allocations')$rows;payments<-.vr_rows(if(is.null(payment_outcomes))list()else payment_outcomes,'payment_outcomes');violations<-traces<-payment_traces<-list();groups<-c('incomes','expenses','contracts','collateral');cutoff<-.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff');issue<-function(code,unit,detail)violations[[length(violations)+1]]<<-list(code=code,unit_id=unit,detail=detail);isbool<-function(x)is.logical(x)&&length(x)==1&&!is.na(x);keyfor<-function(...) .cr_hash(list(...));object<-function(x)if(length(x))x else structure(list(),names=character())
 for(e in proofs){for(k in c('economic_id','reference')).vb_string(e[[k]],k);if(!e$kind%in%groups||!isbool(e$verified)).cr_error('AFFORDABILITY_VALIDATION_EVIDENCE','Explicit kind and verified Boolean required');if(.cr_data_date(e$known_at,'evidence known_at')<.cr_data_date(e$observed_at,'evidence observed_at')).cr_error('AFFORDABILITY_VALIDATION_EVIDENCE','Knowledge precedes observation');terms<-.ex_object(e$terms,'economic terms');.vb_string(terms$currency,'economic currency');if(e$kind=='incomes'){if(!identical(terms$basis,'net')||!e$source_basis%in%c('net','gross')).cr_error('AFFORDABILITY_VALIDATION_INCOME','Normalized net terms and source basis required');amount<-.vb_number(terms$monthly_amount,'monthly net amount');if(e$source_basis=='gross'){gross<-.vb_number(e$monthly_gross_amount,'monthly gross',0);deduct<-.vb_number(e$monthly_tax_and_deductions,'monthly deductions',0);.vb_string(e$normalization_reference,'normalization_reference');if(length(.va_differences(amount,gross-deduct,tol)))issue('GROSS_NET_RECONCILIATION',e$evidence_id,'Verified gross less deductions differs from normalized net income')}}}
 ai<-sums<-sumlabels<-used_households<-list();for(a in shares){for(k in c('economic_id','household_id')).vb_string(a[[k]],k);date<-.cr_data_date(a$as_of,'allocation as_of');known<-.cr_data_date(a$known_at,'allocation known_at');fraction<-.vb_number(a$share,'allocation share',0);if(fraction>1||!a$mode%in%c('PROPORTIONAL','FULL_RECOURSE')).cr_error('AFFORDABILITY_VALIDATION_ALLOCATION','Proportional/full-recourse share in [0,1] required');key<-keyfor(a$economic_id,a$household_id,a$as_of);if(!is.null(ai[[key]])).cr_error('AFFORDABILITY_VALIDATION_ALLOCATION','Duplicate economic/household/as-of allocation');ai[[key]]<-a;if(known>date)issue('ALLOCATION_LOOKAHEAD',a$allocation_id,'Allocation unavailable at its declared as-of');if(a$mode=='PROPORTIONAL'){pool<-keyfor(a$economic_id,a$as_of);sums[[pool]]<-if(is.null(sums[[pool]]))fraction else sums[[pool]]+fraction;sumlabels[[pool]]<-c(a$economic_id,a$as_of)}else if(fraction!=1)issue('FULL_RECOURSE_SHARE',a$allocation_id,'Full recourse requires the entire contractual obligation')};if(length(sums)){ord<-order(vapply(sumlabels,function(x)x[1],character(1)),vapply(sumlabels,function(x)x[2],character(1)));for(pool in names(sums)[ord])if(sums[[pool]]>1+tol)issue('SHARED_ECONOMIC_DOUBLE_COUNT',paste(sumlabels[[pool]],collapse='@'),'Proportional household shares exceed one')};global_evidence_invalid<-length(violations)>0;case_index<-period_index<-period_labels<-list();verified_count<-0
 for(row in rows){identity<-row$prediction_id;household<-.vb_string(row$household_id,'household_id');baseline<-.ex_object(row$baseline,'baseline');scenario<-.ex_object(row$scenario,'scenario');assessment<-.ex_object(row$assessment,'assessment');bindings<-.ex_object(row$evidence_bindings,'evidence_bindings');expected<-.ex_object(row$expected_economic_ids,'expected_economic_ids');if(!setequal(names(expected),groups)).cr_error('AFFORDABILITY_VALIDATION_EXPECTED','Expected IDs for all four groups required');if(!identical(baseline$as_of,row$as_of)||!identical(baseline$currency,currency)).cr_error('AFFORDABILITY_VALIDATION_SCOPE','Baseline as-of/currency differs');for(field in c('scenario_known_at','profile_known_at'))if(.cr_data_date(row[[field]],field)>.cr_data_date(row$forecast_known_at,'forecast_known_at')).cr_error('AFFORDABILITY_VALIDATION_LOOKAHEAD','Scenario and thresholds must precede assessment');.vb_string(row$profile_version,'profile_version');before<-length(violations);allids<-character()
 for(kind in groups){required<-.ex_ids(expected[[kind]],paste(kind,'expected IDs'),empty=TRUE);items<-.vr_rows(baseline[[kind]],paste('baseline',kind));ids<-.ex_ids(lapply(items,function(v)v$economic_id),paste(kind,'actual IDs'),empty=TRUE);allids<-c(allids,ids);if(!setequal(required,ids))issue('MISSING_OR_EXTRA_ECONOMIC_COMPONENT',identity,paste0(kind,' differs from declared required evidence universe'));for(item in items){economic<-item$economic_id;binding<-bindings[[economic]];e<-if(is.null(binding))NULL else ei[[binding]];a<-ai[[keyfor(economic,household,row$as_of)]];if(is.null(e)||e$economic_id!=economic||e$kind!=kind||!e$verified){issue('INCOMPLETE_ECONOMIC_EVIDENCE',identity,paste0(economic,' lacks verified matching source'));next};if(e$known_at>row$forecast_known_at||e$observed_at>row$as_of){issue('ECONOMIC_EVIDENCE_LOOKAHEAD',identity,paste0(economic,' unavailable at original assessment'));next};if(is.null(a)||a$known_at>row$forecast_known_at){issue('MISSING_HOUSEHOLD_ALLOCATION',identity,paste0(economic,' has no historically known household share'));next};if(a$mode=='FULL_RECOURSE'&&kind!='contracts')issue('INVALID_FULL_RECOURSE_COMPONENT',identity,paste0(economic,' is not a contractual obligation'));terms<-e$terms;factor<-a$share;amountfields<-if(kind=='contracts')c('principal','balloon_amount')else if(kind=='collateral')'value'else'monthly_amount';for(field in amountfields)terms[[field]]<-.vb_number(terms[[field]],paste('source',field))*factor;terms$economic_id<-economic;if(length(.va_differences(terms,item,tol)))issue('ECONOMIC_TERM_RECONCILIATION',identity,paste0(economic,' differs from verified allocated source terms'));used_households[[economic]]<-union(used_households[[economic]],household)}}
 if(anyDuplicated(allids))issue('DUPLICATE_ECONOMIC_PURPOSE',identity,'Same source appears in multiple budget groups');if(!setequal(names(bindings),allids))issue('EVIDENCE_BINDING_COVERAGE',identity,'Bindings must cover exactly the frozen economic components');recomputed<-stress_affordability(baseline,scenario)$value;if(tail(recomputed$periods,1)[[1]]$date!=row$horizon_end).cr_error('AFFORDABILITY_VALIDATION_HORIZON','Projection endpoint differs from target');differences<-.va_differences(recomputed,assessment,tol);if(length(differences))issue('FROZEN_ASSESSMENT_RECONCILIATION',identity,paste0('Projection differs at ',paste(differences,collapse=',')));verified<-!global_evidence_invalid&&length(violations)==before;verified_count<-verified_count+verified;case_index[[identity]]<-row;for(period in recomputed$periods){key<-keyfor(identity,period$date);period_index[[key]]<-period;period_labels[[key]]<-c(identity,period$date)};traces[[length(traces)+1]]<-list(prediction_id=identity,household_id=household,verified_projection=verified,recomputed_assessment=recomputed,differing_paths=as.list(differences),positive_residual_implies_zero_pd=FALSE)}
 seen<-character();actual_scheduled<-actual_paid<-payment_weights<-payment_case_positions<-numeric();period_exclusions<-list();positions<-setNames(seq_along(rows),vapply(rows,function(r)r$prediction_id,character(1)));for(p in payments){identity<-p$prediction_id;date<-p$period_date;key<-keyfor(identity,date);if(key%in%seen||is.null(period_index[[key]])).cr_error('AFFORDABILITY_VALIDATION_PAYMENT','Unique payment must match forecast period');seen<-c(seen,key);period<-.cr_data_date(date,'payment period');known<-.cr_data_date(p$known_at,'payment known_at');through<-.cr_data_date(p$observed_through,'payment observed_through');if(known<through||!isbool(p$complete)||!identical(p$currency,currency)).cr_error('AFFORDABILITY_VALIDATION_PAYMENT','Complete capture/currency/subsequent knowledge required');scheduled<-.vb_number(p$scheduled_payment,'actual scheduled payment',0);paid<-.vb_number(p$paid_amount,'actual paid amount',0);reason<-NULL;if(period>cutoff||known>cutoff)reason<-'IMMATURE_OR_UNKNOWN_PAYMENT'else if(!p$complete||through<period)reason<-'INCOMPLETE_PAYMENT_CAPTURE';if(!is.null(reason)){period_exclusions[[length(period_exclusions)+1]]<-list(prediction_id=identity,period_date=date,reason=reason)}else{actual_scheduled<-c(actual_scheduled,scheduled);actual_paid<-c(actual_paid,paid);cw<-case_index[[identity]]$weight;payment_weights<-c(payment_weights,.vb_number(if(is.null(cw))1 else cw,'case weight',0));payment_case_positions<-c(payment_case_positions,positions[[identity]])};payment_traces[[length(payment_traces)+1]]<-list(prediction_id=identity,period_date=date,eligible=is.null(reason),actual_scheduled_payment=scheduled,actual_paid_amount=paid,projected_scenario_debt_service=period_index[[key]]$debt_service,scenario_equals_realized_claimed=FALSE)}
 metric<-function(draw).vb_errors(actual_scheduled,actual_paid,payment_weights*draw[payment_case_positions]);factual<-metric(rep(1,length(rows)));draws<-.vb_draws(uncertainty,cluster_resamples,rows,confidence_level);samples<-if(is.null(draws))NULL else lapply(draws,function(draw){m<-metric(draw);list(bias=m$bias,rmse=m$rmse)});missing<-setdiff(names(period_index),seen);if(length(missing))missing<-missing[order(vapply(period_labels[missing],function(x)x[1],character(1)),vapply(period_labels[missing],function(x)x[2],character(1)))];payload<-list(design=d,applicability=if(length(rows))'APPLICABLE'else'NOT_APPLICABLE',metrics=list(cases=length(rows),verified_projection_cases=verified_count,factual_scheduled_minus_paid=factual),uncertainty=.vb_bands(samples,confidence_level),projection_traces=traces,payment_traces=payment_traces,payment_exclusions=period_exclusions,missing_payment_periods=lapply(missing,function(key)list(prediction_id=period_labels[[key]][1],period_date=period_labels[[key]][2])),economic_dependence=object(lapply(used_households[sort(names(used_households))],function(v)as.list(sort(v)))),scenario_projection_is_default_probability=FALSE,factual_payments_are_scenario_realization=FALSE);result<-.vs_finish('affordability_stress_backtest',payload,violations,list(cases=rows,economic_evidence=proofs,allocations=shares,payment_outcomes=payments,design=d),context);if(!length(rows))result$value$decision$status<-'NOT_APPLICABLE';result
}
